import React, { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Download, AlertTriangle, CheckCircle, XCircle, Info, ExternalLink } from 'lucide-react';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:4000/api';

export default function SessionView() {
  const { id } = useParams();
  const [session, setSession] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get(`${API_URL}/verification-session/${id}`)
      .then(res => setSession(res.data.session))
      .catch(err => console.error(err))
      .finally(() => setLoading(false));
  }, [id]);

  if (loading) return <div style={{ textAlign: 'center', marginTop: '40px' }}>Loading session...</div>;
  if (!session) return <div style={{ textAlign: 'center', marginTop: '40px' }}>Session not found.</div>;

  const results = session.results || session.certResults || [session.result].filter(Boolean);

  const getStatusIcon = (status) => {
    if (status === 'REAL') return <CheckCircle size={20} />;
    if (status === 'SUSPICIOUS') return <AlertTriangle size={20} />;
    if (status === 'FAKE') return <XCircle size={20} />;
    return <Info size={20} />;
  };

  const handleDownloadPDF = () => {
    window.open(`${API_URL}/report/${id}/pdf`, '_blank');
  };

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '32px' }}>
        <div>
          <h2 style={{ fontSize: '2rem', marginBottom: '8px' }}>Verification Report</h2>
          <p style={{ color: 'var(--text-secondary)' }}>
            Session ID: {id} • {new Date(session.timestamp).toLocaleString()}
          </p>
        </div>
        <button onClick={handleDownloadPDF} className="btn-primary">
          <Download size={18} /> Download PDF
        </button>
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '16px', marginBottom: '32px' }}>
        <div className="glass-panel" style={{ textAlign: 'center' }}>
          <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--text-primary)' }}>{session.summary.total}</div>
          <div style={{ color: 'var(--text-secondary)' }}>Total Links Processed</div>
        </div>

        <div className="glass-panel" style={{ textAlign: 'center', borderColor: 'var(--status-real)' }}>
          <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--status-real)' }}>{session.summary.REAL}</div>
          <div style={{ color: 'var(--status-real)' }}>Authentic</div>
        </div>
        <div className="glass-panel" style={{ textAlign: 'center', borderColor: 'var(--status-suspicious)' }}>
          <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--status-suspicious)' }}>{session.summary.SUSPICIOUS}</div>
          <div style={{ color: 'var(--status-suspicious)' }}>Suspicious</div>
        </div>
        <div className="glass-panel" style={{ textAlign: 'center', borderColor: 'var(--status-fake)' }}>
          <div style={{ fontSize: '2rem', fontWeight: 'bold', color: 'var(--status-fake)' }}>{session.summary.FAKE}</div>
          <div style={{ color: 'var(--status-fake)' }}>Fraudulent</div>
        </div>
      </div>



      {session.candidateName && (
        <div className="glass-panel" style={{ marginBottom: '32px', background: 'rgba(59, 130, 246, 0.05)', borderColor: 'var(--accent-primary)' }}>
          <h3 style={{ color: 'var(--accent-primary)', marginBottom: '8px' }}>Resume Intelligence</h3>
          <div style={{ display: 'flex', gap: '32px' }}>
            <div>
              <span style={{ color: 'var(--text-secondary)', display: 'block', fontSize: '0.875rem' }}>Candidate Name</span>
              <strong>{session.candidateName}</strong>
            </div>
            {session.skills && session.skills.length > 0 && (
              <div>
                <span style={{ color: 'var(--text-secondary)', display: 'block', fontSize: '0.875rem' }}>Extracted Skills</span>
                <div style={{ display: 'flex', gap: '8px', flexWrap: 'wrap', marginTop: '4px' }}>
                  {session.skills.map(s => (
                    <span key={s} style={{ background: 'var(--glass-border)', padding: '2px 8px', borderRadius: '4px', fontSize: '0.875rem' }}>{s}</span>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      <h3 style={{ fontSize: '1.5rem', marginBottom: '16px' }}>Detailed Results</h3>
      <div style={{ display: 'grid', gap: '16px' }}>
        {results.map((result, i) => (
          <div key={i} className="glass-panel" style={{ position: 'relative', overflow: 'hidden' }}>
            {/* Status Indicator Line */}
            <div style={{ 
              position: 'absolute', left: 0, top: 0, bottom: 0, width: '4px',
              background: result.status === 'REAL' ? 'var(--status-real)' : result.status === 'SUSPICIOUS' ? 'var(--status-suspicious)' : result.status === 'FAKE' ? 'var(--status-fake)' : 'var(--status-error)'
            }} />

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: '16px' }}>
              <div>
                <h4 style={{ fontSize: '1.25rem', marginBottom: '4px' }}>{result.fileName}</h4>
                {result.platform && <span style={{ color: 'var(--text-secondary)', fontSize: '0.875rem' }}>Platform: {result.platform}</span>}
                {result.mentionedName && (
                  <div style={{ marginTop: '4px', fontSize: '0.875rem' }}>
                    <span style={{ color: 'var(--text-secondary)' }}>Mentioned as: </span>
                    <strong style={{ color: 'var(--accent-secondary)' }}>{result.mentionedName}</strong>
                  </div>
                )}
                {result.verifiedViaLink !== undefined && (
                  <div style={{ marginTop: '4px', fontSize: '0.875rem' }}>
                    <span style={{ color: 'var(--text-secondary)' }}>Verified via Link: </span>
                    <strong style={{ color: result.verifiedViaLink ? 'var(--status-real)' : 'var(--status-suspicious)' }}>
                      {result.verifiedViaLink ? 'Yes' : 'No'}
                    </strong>
                  </div>
                )}
              </div>
              <span className={`status-badge ${result.status.toLowerCase()}`}>
                {getStatusIcon(result.status)} 
                <span style={{ marginLeft: '4px' }}>
                  {result.status === 'REAL' ? 'Authentic' : result.status === 'FAKE' ? 'Fraudulent' : 'Suspicious'} 
                  ({(result.confidence * 100).toFixed(0)}%)
                </span>
              </span>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', marginBottom: '16px', background: 'rgba(0,0,0,0.2)', padding: '16px', borderRadius: '8px' }}>
              <div>
                <span style={{ color: 'var(--text-secondary)', display: 'block', fontSize: '0.875rem' }}>Detected Name</span>
                <strong>{result.detectedName || 'Unknown'}</strong>
              </div>
              <div>
                <span style={{ color: 'var(--text-secondary)', display: 'block', fontSize: '0.875rem' }}>Verified Name (Source)</span>
                {result.verifiedName ? (
                  <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <strong>{result.verifiedName}</strong>
                    {result.verificationUrl && (
                      <a href={result.verificationUrl} target="_blank" rel="noreferrer" style={{ color: 'var(--accent-primary)' }}>
                        <ExternalLink size={14} />
                      </a>
                    )}
                  </div>
                ) : 'Not found'}
              </div>
            </div>

            {result.reasons && result.reasons.length > 0 && (
              <div>
                <h5 style={{ fontSize: '1rem', marginBottom: '8px', color: 'var(--text-secondary)' }}>Analysis Log</h5>
                <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
                  {result.reasons.map((reason, idx) => (
                    <li key={idx} style={{ marginBottom: '4px', fontSize: '0.875rem', display: 'flex', gap: '8px' }}>
                      <span style={{ color: 'var(--accent-secondary)' }}>•</span> {reason}
                    </li>
                  ))}
                </ul>
              </div>
            )}
          </div>
        ))}
      </div>
    </motion.div>
  );
}
